def get_svg_data_uri(svg_string: str, stroke_color: str = None) -> str:
    """Encodes an SVG string into a base64 data URI, optionally replacing currentColor."""
    clean_svg = svg_string.strip()
    if stroke_color:
        clean_svg = clean_svg.replace("currentColor", stroke_color)
    encoded = base64.b64encode(clean_svg.encode("utf-8")).decode("utf-8")
    return f"data:image/svg+xml;base64,{encoded}"


def clean_html(raw_html: str) -> str:
    """Strips leading/trailing whitespace on every line and removes blank lines
    so CommonMark in st.markdown never interprets indented HTML/CSS as a <pre><code> block."""
    return "\n".join(line.strip() for line in raw_html.splitlines() if line.strip())
